    xsmall: 182px,
    small: 274px,
    medium: 381px,
    large: 466px,
    xlarge: 583px,
  ),
);

// content grid numbers for width calculation
$gridOffsetColumns: (
  tiny: 6,
  small: 10,
  medium: 9,
  large: 8,
);

/**
 * Breakpoint Variables for Foundation Grid
 */
$breakpoints: (
  tiny: $sizeBreakpointZero,
  xsmall: $sizeBreakpointXSmall,
  small: $sizeBreakpointSmall,
  medium: $sizeBreakpointMedium,
  large: $sizeBreakpointLarge,
  xlarge: $sizeBreakpointXLarge,
);

$grid-margin-gutters: (
  tiny: $sizeSmallRegular,
  xsmall: $sizeRegular,
  medium: $sizeLarge,
  large: $sizeLarge,
  xlarge: $sizeBig,
);

$grid-outer-gutters: (
  bleed: (
    tiny: $sizeSmallRegular,
    xsmall: $sizeRegular,
    small: $sizeBig,
    large: $sizeBiggerBig,
    xlarge: 0,
  ),
  contentWidthBleed: (
    large: math.div($sizeSmallHuge, 2),
    xlarge: 0,
  ),
);

$breakpoint-classes: (tiny xsmall small medium large xlarge);

/**
 * Custom colors
 */
$colorBlack: #000;
$colorBlack80: #333;
$colorBlack60: #666;
$colorBlack40: #949494;
$colorBlack20: #ccc;
$colorBlack15: #d9d9d9;
