$colorBg: $colorBlack5;

/**
 * Color variations
 */
$tl-color-variations: (
  cv-blue: $colorBlue,
  cv-darkblue: $colorDarkBlue,
  cv-turqoise: $colorTurqoise,
  cv-green: $colorGreen,
  cv-bordeaux: $colorBordeaux,
  cv-magenta: $colorMagenta,
  cv-violet: $colorViolet,
