/**
 * Transition and Easings and Timings
 */

$transitionTimeSimple: 100ms;
$transitionTimeFade: 200ms;
$transitionTimeFadeIn: $transitionTimeFade;
$transitionTimeFadeOut: $transitionTimeFade;
