/*!
 * Design	tokens – Kanton Zürich
 *
 * Derived from the official design system repository
 * https://github.com/Kanton-Zurich/frontend-designsystem (Apache-2.0),
 * file `src/assets/css/globals/_variables.scss` (retrieved 2026-10-18) plus
 * the guidance at https://www.zh.ch/de/webangebote-entwickeln-und-gestalten.html.
 *
 * Values are copied 1:1; only the naming scheme is ours (`--zh-*`), so the app
 * stays recognisably Cantonal without redistributing the upstream SCSS.
 * Inter (SIL OFL 1.1, see public/fonts/LICENSE-Inter-OFL.txt) is self-hosted,
 * same files the canton ships.
 */

/* Fonts: same families and files as the official frontend (`_fonts.scss`). */
@font-face {
  font-family: 'InterRegular';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('/fonts/Inter-Regular.woff2') format('woff2');
}
@font-face {
  font-family: 'InterBlack';
  font-style: normal;
  font-weight: 900;
  font-display: swap;
  src: url('/fonts/Inter-Black.woff2') format('woff2');
}

:root {
  /* ---- Colours (official token names in comments) ---- */
  --zh-black: #000; /* $colorBlack */
  --zh-black-80: #333; /* $colorBlack80 */
  --zh-black-60: #666; /* $colorBlack60 – $colorAnthracite */
  --zh-black-40: #949494; /* $colorBlack40 */
  --zh-black-20: #ccc; /* $colorBlack20 */
  --zh-black-15: #d9d9d9; /* $colorBlack15 */
  --zh-black-10: #f0f0f0; /* $colorBlack10 */
  --zh-black-5: #f7f7f7; /* $colorBlack5 – $colorBg */
  --zh-white: #fff;

  --zh-blue: #0070b4; /* $colorBlue */
  --zh-darkblue: #00407c; /* $colorDarkBlue */
  --zh-turquoise: #00797b; /* $colorTurqoise */
  --zh-bordeaux: #b01657; /* $colorBordeaux */
  --zh-magenta: #d40053; /* $colorMagenta */
  --zh-violet: #7f3da7; /* $colorViolet */
  --zh-green: #1a7f1f; /* $colorGreen */
  --zh-cyan: #009ee0; /* $colorCyan */
  --zh-red: #e2001a; /* $colorRed */

  --zh-blue-soft: #edf5fa;
  --zh-darkblue-soft: #e0e8ee;
  --zh-turquoise-soft: #e8f3f2;
  --zh-bordeaux-soft: #f6e3ea;
  --zh-magenta-soft: #fcedf3;
  --zh-violet-soft: #ece2f1;
  --zh-green-soft: #ebf6eb;
  --zh-neutral-soft: var(--zh-black-10);

  /* Semantic colours */
  --zh-color-text: var(--zh-black);
  --zh-color-text-soft: var(--zh-black-60);
  --zh-color-bg: var(--zh-black-5);
  --zh-color-surface: var(--zh-white);
  --zh-color-border: var(--zh-black-15);
  --zh-color-border-strong: var(--zh-black-20);
  --zh-color-accent: var(--zh-blue);
  --zh-color-accent-dark: var(--zh-darkblue);
  --zh-color-focus: var(--zh-blue);
  --zh-color-danger: var(--zh-red);
  --zh-color-warning: var(--zh-bordeaux);
  --zh-color-success: var(--zh-green);

  /* ---- Typography ---- */
  --zh-font-base: 'InterRegular', 'Inter', Helvetica, Arial, sans-serif;
  --zh-font-black: 'InterBlack', 'Inter', 'Arial Black', Helvetica, sans-serif;
  --zh-font-mono: ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, monospace;

  --zh-font-mini: 10px; /* $sizeFontMini */
  --zh-font-tiny: 12px; /* $sizeFontTiny */
  --zh-font-small: 14px; /* $sizeFontSmall */
  --zh-font-regular: 16px; /* $sizeFontRegular (base) */
  --zh-font-bigger-regular: 18px; /* $sizeFontBiggerRegular */
  --zh-font-medium: 20px; /* $sizeFontMedium */
  --zh-font-large: 24px; /* $sizeFontLarge */
  --zh-font-small-big: 28px; /* $sizeFontSmallBig */
  --zh-font-big: 32px; /* $sizeFontBig */
  --zh-font-bigger-big: 40px; /* $sizeFontBiggerBig */
  --zh-font-small-huge: 48px; /* $sizeFontSmallHuge */
  --zh-font-huge: 56px; /* $sizeFontHuge */
  --zh-font-giant: 72px; /* $sizeFontGiant */

  --zh-line-narrower: 1; /* $sizeLineHeightNarrower */
  --zh-line-narrow: 1.2; /* $sizeLineHeightNarrow */
  --zh-line-medium: 1.3; /* $sizeLineHeightMedium */
  --zh-line-bigger: 1.4; /* $sizeLineHeightBigger */
  --zh-line-base: 1.5; /* $sizeLineHeightBase */
  --zh-line-super: 1.8; /* $sizeLineHeightSuper */

  /* ---- Spacing scale ($sizeMini … $sizeGiant) ---- */
  --zh-size-mini: 4px;
  --zh-size-tiny: 8px;
  --zh-size-small-regular: 12px;
  --zh-size-regular: 16px;
  --zh-size-small-large: 20px;
  --zh-size-large: 24px;
  --zh-size-small-big: 28px;
  --zh-size-big: 32px;
  --zh-size-bigger-big: 40px;
  --zh-size-small-huge: 48px;
  --zh-size-huge: 56px;
  --zh-size-giant: 80px;

  /* ---- Layout ---- */
  --zh-max-width: 1440px; /* $sizeGlobalMaxWidth */
  --zh-content-width: 1168px; /* $sizeWidthContent */
  --zh-text-width: 768px; /* $sizeWidthTextContent */
  --zh-column-gap: 12px; /* columnGap curve, tiny */
  --zh-wrapper-gap: 12px;

  /* Characteristic indentation of the cantonal design: content and headings sit
     on a 4px rhythm rule, section headings carry a 3px top border and a
     colour-variation bar on the left (see atm-heading--bordered, anchorlink). */
  --zh-indent: 12px;
  --zh-rule: 3px;

  /* ---- Shape, motion, layers ---- */
  --zh-radius: 1px; /* buttons: border-radius: 1px */
  --zh-radius-tag: 5px; /* atm-tag */
  --zh-transition-simple: 100ms;
  --zh-transition-fade: 200ms;
  --zh-transition-default: 250ms;
  --zh-easing-default: ease;
  --zh-easing-decelerate: cubic-bezier(0.01, 0.13, 0.63, 0.99);

  --zh-z-header: 100;
  --zh-z-overlay: 1000;
  --zh-z-detail: 1100;
  --zh-z-skiplink: 2000;

  --zh-shadow-card: 0 1px 2px rgb(0 0 0 / 6%), 0 8px 24px rgb(0 0 0 / 6%);
  --zh-shadow-header: 0 1px 0 var(--zh-color-border);
}

@media (min-width: 600px) {
  :root {
    --zh-indent: 16px;
    --zh-column-gap: 16px;
    --zh-wrapper-gap: 16px;
  }
}
@media (min-width: 840px) {
  :root {
    --zh-column-gap: 24px;
    --zh-wrapper-gap: 24px;
  }
}
@media (min-width: 1280px) {
  :root {
    --zh-column-gap: 32px;
    --zh-wrapper-gap: 32px;
    --zh-indent: 24px;
  }
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --zh-transition-simple: 0ms;
    --zh-transition-fade: 0ms;
    --zh-transition-default: 0ms;
  }
}

/*!
 * Base layer – Kanton Zürich design system
 * Typography, focus states, layout shell, accessibility utilities.
 */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--zh-color-bg);
  color: var(--zh-color-text);
  font-family: var(--zh-font-base);
  font-size: var(--zh-font-regular);
  line-height: var(--zh-line-base);
}

img,
svg,
video {
  max-width: 100%;
}

/* ---- Headings: InterBlack, tight tracking (atm-heading) ---- */
h1,
h2,
h3,
h4,
h5,
h6,
.zh-heading {
  margin: 0 0 var(--zh-size-regular);
  font-family: var(--zh-font-black);
  font-weight: 900;
  line-height: var(--zh-line-narrow);
  letter-spacing: -0.02em;
  color: var(--zh-color-text);
  hyphens: auto;
}

h1,
.zh-heading--1 {
  font-size: var(--zh-font-big);
  line-height: var(--zh-line-narrower);
}

.zh-heading--2 {
  font-size: var(--zh-font-small-big);
}

.zh-heading--3 {
  font-size: var(--zh-font-large);
}

.zh-heading--4,
h4 {
  font-size: var(--zh-font-bigger-regular);
  letter-spacing: -0.01em;
}

/* Bordered heading = cantonal section marker: 3px rule, content indented. */
.zh-heading--bordered {
  position: relative;
  padding-top: calc(var(--zh-size-small-regular) + var(--zh-rule));
  border-top: none;
}

.zh-heading--bordered::before {
  content: '';
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  height: var(--zh-rule);
  background: var(--zh-color-text);
}

@media (min-width: 840px) {
  h1,
  .zh-heading--1 {
    font-size: var(--zh-font-bigger-big);
  }
  .zh-heading--2 {
    font-size: var(--zh-font-big);
  }
  .zh-heading--3 {
    font-size: var(--zh-font-small-big);
  }
  .zh-heading--4,
  h4 {
    font-size: var(--zh-font-medium);
  }
}

@media (min-width: 1280px) {
  h1,
  .zh-heading--1 {
    font-size: var(--zh-font-small-huge);
  }
  .zh-heading--2 {
    font-size: var(--zh-font-bigger-big);
  }
  .zh-heading--3 {
    font-size: var(--zh-font-big);
  }
}

p {
  margin: 0 0 var(--zh-size-regular);
  max-width: var(--zh-text-width);
}

.zh-lead {
  font-size: var(--zh-font-bigger-regular);
  line-height: var(--zh-line-bigger);
  color: var(--zh-color-text);
  margin-bottom: var(--zh-size-large);
}

a {
  color: var(--zh-color-accent-dark);
  text-decoration: underline;
  text-underline-offset: 0.15em;
  text-decoration-thickness: 1px;
}

a:hover {
  color: var(--zh-black);
  text-decoration-thickness: 2px;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
summary:focus-visible,
[tabindex]:focus-visible {
  outline: 3px solid var(--zh-color-focus);
  outline-offset: 2px;
  border-radius: var(--zh-radius);
}

/* Non-interactive outline must never disappear on dark surfaces. */
.zh-inverted a:focus-visible {
  outline-color: var(--zh-white);
}

kbd {
  display: inline-block;
  padding: 1px 5px;
  border: 1px solid var(--zh-color-border-strong);
  border-bottom-width: 2px;
  border-radius: 3px;
  background: var(--zh-white);
  font-family: var(--zh-font-mono);
  font-size: var(--zh-font-tiny);
  line-height: 1.4;
}

code {
  font-family: var(--zh-font-mono);
  font-size: 0.9em;
  background: var(--zh-black-10);
  padding: 1px 4px;
  border-radius: 2px;
}

hr {
  border: 0;
  border-top: var(--zh-rule) solid var(--zh-color-text);
  margin: var(--zh-size-large) 0;
}

/* ---- Layout shell ---- */
.zh-shell {
  width: 100%;
  max-width: var(--zh-content-width);
  margin-inline: auto;
  padding-inline: var(--zh-wrapper-gap);
}

@media (min-width: 1280px) {
  .zh-shell {
    padding-inline: var(--zh-size-big);
  }
}

/* ---- Utilities ---- */
.visuallyhidden,
.zh-visuallyhidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.zh-skiplink {
  position: absolute;
  left: var(--zh-size-regular);
  top: -100px;
  z-index: var(--zh-z-skiplink);
  padding: var(--zh-size-tiny) var(--zh-size-regular);
  background: var(--zh-black);
  color: var(--zh-white);
  font-family: var(--zh-font-black);
  text-decoration: none;
}

.zh-skiplink:focus {
  top: var(--zh-size-regular);
}

.zh-hint {
  font-size: var(--zh-font-small);
  color: var(--zh-color-text-soft);
  margin: 0 0 var(--zh-size-tiny);
}

.zh-state {
  padding: var(--zh-size-large);
  border: 1px solid var(--zh-color-border);
  border-left: var(--zh-size-mini) solid var(--zh-color-accent);
  background: var(--zh-color-surface);
  color: var(--zh-color-text);
  font-size: var(--zh-font-small);
}

.zh-state--error {
  border-left-color: var(--zh-color-danger);
}

.zh-state--empty {
  border-left-color: var(--zh-black-40);
}

.zh-state__title {
  display: block;
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-regular);
  margin-bottom: var(--zh-size-mini);
}

/* Loading indicator (loading_circle.scss: cyan, 24px, 2px border) */
.zh-spinner {
  display: inline-block;
  width: var(--zh-font-large);
  height: var(--zh-font-large);
  border: 2px solid var(--zh-black-20);
  border-top-color: var(--zh-cyan);
  border-radius: 50%;
  animation: zh-spin 900ms linear infinite;
  vertical-align: middle;
}

@keyframes zh-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .zh-spinner {
    animation-duration: 3s;
  }
  html {
    scroll-behavior: auto;
  }
}

/*!
 * Components – derived from the Kanton Zürich frontend atoms
 * (atm-button, atm-form_input, atm-tag, atm-heading, search_result_item,
 *  layout/header, layout/footer). Shapes, colours and focus behaviour follow
 *  the official SCSS; the markup here is our own.
 */

/* ---------- Buttons (button.scss: black fill, 1px radius, black weight) ---------- */
.zh-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--zh-size-small-regular);
  min-height: var(--zh-size-bigger-big);
  min-width: var(--zh-size-bigger-big);
  padding: 1px var(--zh-size-large) 0;
  border: none;
  border-radius: var(--zh-radius);
  background: var(--zh-black);
  color: var(--zh-white);
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-regular);
  font-weight: 900;
  line-height: var(--zh-line-bigger);
  text-decoration: none;
  cursor: pointer;
  transition: background var(--zh-transition-simple) var(--zh-easing-default);
}

.zh-button:hover {
  background: var(--zh-black-80);
  color: var(--zh-white);
}

.zh-button:disabled,
.zh-button[aria-disabled='true'] {
  background: var(--zh-black-40);
  cursor: not-allowed;
}

.zh-button--small {
  min-height: var(--zh-size-big);
  padding: 0 var(--zh-size-regular);
  font-size: var(--zh-font-small);
}

.zh-button--secondary {
  background: var(--zh-color-accent-dark);
}

.zh-button--secondary:hover {
  background: var(--zh-black);
}

.zh-button--ghost {
  background: transparent;
  color: var(--zh-black);
  border: 2px solid var(--zh-black);
}

.zh-button--ghost:hover {
  background: var(--zh-black-10);
  color: var(--zh-black);
}

.zh-button--icon {
  padding: 0;
  width: var(--zh-size-bigger-big);
}

.zh-button__icon {
  width: 16px;
  height: 16px;
  flex: none;
  fill: currentColor;
}

/* ---------- Chips (compact toggles, tag.scss geometry) ---------- */
.zh-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--zh-size-mini);
  padding: var(--zh-size-mini) var(--zh-size-tiny);
  border: 2px solid var(--zh-color-border-strong);
  border-radius: var(--zh-radius-tag);
  background: var(--zh-white);
  color: var(--zh-black-60);
  font-family: var(--zh-font-base);
  font-size: var(--zh-font-tiny);
  line-height: 1.4;
  cursor: pointer;
  transition: border-color var(--zh-transition-simple) var(--zh-easing-default),
    color var(--zh-transition-simple) var(--zh-easing-default);
}

.zh-chip:hover {
  border-color: var(--zh-black);
  color: var(--zh-black);
}

.zh-chip[aria-pressed='true'],
.zh-chip.is-active {
  background: var(--zh-black);
  border-color: var(--zh-black);
  color: var(--zh-white);
}

/* ---------- Tags (atm-tag) ---------- */
.zh-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--zh-size-tiny);
  margin: 0;
  padding: 0;
  list-style: none;
}

.zh-tag {
  display: inline-flex;
  align-items: center;
  gap: var(--zh-size-mini);
  width: fit-content;
  padding: var(--zh-size-mini) var(--zh-size-tiny);
  border: 2px solid var(--zh-color-border-strong);
  border-radius: var(--zh-radius-tag);
  color: var(--zh-black-60);
  font-size: var(--zh-font-tiny);
  line-height: 1.4;
}

.zh-tag--blue {
  border-color: var(--zh-blue);
  color: var(--zh-darkblue);
  background: var(--zh-blue-soft);
}

.zh-tag--turquoise {
  border-color: var(--zh-turquoise);
  color: var(--zh-turquoise);
  background: var(--zh-turquoise-soft);
}

.zh-tag--green {
  border-color: var(--zh-green);
  color: var(--zh-green);
  background: var(--zh-green-soft);
}

.zh-tag--solid {
  background: var(--zh-black);
  border-color: var(--zh-black);
  color: var(--zh-white);
}

/* ---------- Form controls (form_input.scss) ---------- */
.zh-label,
.zh-legend {
  display: block;
  margin-bottom: var(--zh-size-mini);
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-small);
  font-weight: 900;
  color: var(--zh-color-text);
}

.zh-input,
.zh-select {
  width: 100%;
  min-height: var(--zh-size-bigger-big);
  padding: var(--zh-size-tiny) var(--zh-size-small-regular);
  border: 2px solid var(--zh-black);
  border-radius: var(--zh-radius);
  background: var(--zh-white);
  color: var(--zh-black);
  font-family: var(--zh-font-base);
  font-size: var(--zh-font-regular);
}

.zh-input--small {
  min-height: var(--zh-size-big);
  font-size: var(--zh-font-small);
}

.zh-input::placeholder {
  color: var(--zh-black-60);
}

.zh-input:focus-visible,
.zh-select:focus-visible {
  outline: 3px solid var(--zh-color-focus);
  outline-offset: 2px;
}

.zh-input[aria-invalid='true'] {
  border-color: var(--zh-red);
}

input[type='range'].zh-input {
  min-height: var(--zh-size-large);
  padding: 0;
  border: 0;
  accent-color: var(--zh-color-accent);
}

.zh-field {
  margin-bottom: var(--zh-size-small-regular);
}

.zh-field--inline {
  display: flex;
  align-items: center;
  gap: var(--zh-size-tiny);
}

.zh-fieldset {
  margin: 0 0 var(--zh-size-large);
  padding: 0;
  border: 0;
}

.zh-checks {
  display: flex;
  flex-direction: column;
  gap: var(--zh-size-tiny);
}

.zh-check {
  display: flex;
  align-items: flex-start;
  gap: var(--zh-size-tiny);
  font-size: var(--zh-font-small);
  cursor: pointer;
}

.zh-check input {
  inline-size: 18px;
  block-size: 18px;
  margin: 2px 0 0;
  accent-color: var(--zh-color-accent-dark);
  flex: none;
}

/* ---------- Panel (details/summary) ---------- */
.zh-panel {
  background: var(--zh-color-surface);
  border: 1px solid var(--zh-color-border);
  border-top: var(--zh-rule) solid var(--zh-color-text);
  margin-bottom: var(--zh-size-regular);
}

.zh-panel__summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--zh-size-tiny);
  padding: var(--zh-size-small-regular) var(--zh-size-regular);
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-bigger-regular);
  font-weight: 900;
  cursor: pointer;
  list-style: none;
}

.zh-panel__summary::-webkit-details-marker {
  display: none;
}

.zh-panel__summary::after {
  content: '▾';
  font-size: var(--zh-font-small);
  transition: transform var(--zh-transition-fade) var(--zh-easing-default);
}

.zh-panel[open] .zh-panel__summary::after {
  transform: rotate(180deg);
}

.zh-panel__body {
  padding: 0 var(--zh-size-regular) var(--zh-size-regular);
}

/* ---------- Cards / result items ---------- */
.zh-card {
  background: var(--zh-color-surface);
  border: 1px solid var(--zh-color-border);
  border-left: var(--zh-size-mini) solid var(--zh-color-accent);
  padding: var(--zh-size-regular);
}

.zh-deflist {
  margin: 0;
  font-size: var(--zh-font-small);
}

.zh-deflist dt {
  font-family: var(--zh-font-black);
  margin-top: var(--zh-size-small-regular);
}

.zh-deflist dd {
  margin: 0 0 var(--zh-size-mini);
  color: var(--zh-color-text-soft);
}

.zh-deflist dd a {
  word-break: break-word;
}

/* ---------- Site header ---------- */
.zh-header {
  background: var(--zh-white);
  box-shadow: var(--zh-shadow-header);
  position: relative;
  z-index: var(--zh-z-header);
}

.zh-header__bar {
  background: var(--zh-black);
  color: var(--zh-white);
}

.zh-header__bar-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--zh-size-tiny);
  min-height: var(--zh-size-big);
  padding-block: var(--zh-size-mini);
}

.zh-header__note {
  margin: 0;
  font-size: var(--zh-font-tiny);
  color: var(--zh-black-20);
  max-width: 60ch;
}

.zh-header__note a {
  color: var(--zh-white);
}

.zh-header__meta {
  display: flex;
  gap: var(--zh-size-regular);
  font-size: var(--zh-font-tiny);
}

.zh-header__meta a {
  color: var(--zh-white);
}

.zh-header__main {
  display: grid;
  gap: var(--zh-size-regular);
  padding-block: var(--zh-size-large);
}

@media (min-width: 840px) {
  .zh-header__main {
    grid-template-columns: minmax(240px, 320px) minmax(320px, 1fr);
    align-items: center;
  }
}

.zh-brand {
  display: flex;
  align-items: center;
  gap: var(--zh-size-small-regular);
  text-decoration: none;
  color: var(--zh-black);
}

.zh-brand:hover {
  color: var(--zh-black);
}

.zh-brand__mark {
  width: 34px;
  height: 41px;
  flex: none;
}

.zh-brand__text {
  display: flex;
  flex-direction: column;
}

.zh-brand__name {
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-large);
  font-weight: 900;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.zh-brand__claim {
  font-size: var(--zh-font-small);
  color: var(--zh-color-text-soft);
}

/* ---------- Search + suggestions (combobox) ---------- */
.zh-search {
  position: relative;
}

.zh-search__field {
  display: flex;
  gap: var(--zh-size-tiny);
}

.zh-search__input {
  flex: 1 1 auto;
  min-width: 0;
}

.zh-search__status {
  margin: var(--zh-size-mini) 0 0;
  font-size: var(--zh-font-small);
  color: var(--zh-color-text-soft);
  min-height: 1.4em;
}

.zh-suggestions {
  position: absolute;
  z-index: var(--zh-z-overlay);
  inset-inline: 0;
  top: calc(100% - 1.4em);
  margin: 0;
  padding: var(--zh-size-mini);
  list-style: none;
  background: var(--zh-white);
  border: 1px solid var(--zh-black);
  box-shadow: var(--zh-shadow-card);
  max-height: 60vh;
  overflow: auto;
}

.zh-suggestions li {
  margin: 0;
}

.zh-suggestions button {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--zh-size-tiny);
  width: 100%;
  padding: var(--zh-size-tiny) var(--zh-size-small-regular);
  border: 0;
  background: transparent;
  font: inherit;
  font-size: var(--zh-font-small);
  text-align: left;
  cursor: pointer;
}

.zh-suggestions button[aria-selected='true'],
.zh-suggestions button:hover {
  background: var(--zh-blue-soft);
}

.zh-suggestions .zh-suggestions__type {
  color: var(--zh-color-text-soft);
  font-size: var(--zh-font-tiny);
  white-space: nowrap;
}

/* ---------- Footer ---------- */
.zh-footer {
  margin-top: var(--zh-size-small-huge);
  background: var(--zh-white);
  border-top: var(--zh-rule) solid var(--zh-black);
  padding-block: var(--zh-size-large);
  font-size: var(--zh-font-small);
}

.zh-footer__inner {
  display: grid;
  gap: var(--zh-size-small-regular);
}

.zh-footer p {
  margin: 0;
  max-width: none;
}

.zh-footer__links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--zh-size-small-regular);
  margin: 0;
  padding: 0;
  list-style: none;
}

.zh-footer__fine {
  color: var(--zh-color-text-soft);
  font-size: var(--zh-font-tiny);
}

/*!
 * App layout – Kartenzeit (historical map explorer).
 * Composition only; visual language comes from the canton tokens/components.
 */

.app-main {
  padding-block: var(--zh-size-large) 0;
}

.app-intro {
  background: var(--zh-white);
  border: 1px solid var(--zh-color-border);
  padding: var(--zh-size-large) var(--zh-size-regular);
  margin-bottom: var(--zh-size-large);
}

.app-intro p {
  margin-bottom: var(--zh-size-small-regular);
}

.app-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--zh-size-small-regular);
  padding: var(--zh-size-small-regular) var(--zh-size-regular);
  background: var(--zh-black-5);
  border-top: var(--zh-rule) solid var(--zh-black);
  margin-bottom: var(--zh-size-regular);
}

.app-toolbar__group {
  display: flex;
  align-items: center;
  gap: var(--zh-size-tiny);
}

.app-toolbar__label {
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-bigger-regular);
  font-weight: 900;
}

.app-toolbar .zh-label {
  margin: 0;
}

.app-toolbar .zh-select {
  width: auto;
  min-height: var(--zh-size-big);
  font-size: var(--zh-font-small);
}

/* ---- Two-column work area: list side + map ---- */
.app-grid {
  display: grid;
  gap: var(--zh-column-gap);
  align-items: start;
}

@media (min-width: 1024px) {
  .app-grid {
    grid-template-columns: minmax(320px, 5fr) minmax(320px, 7fr);
  }
}

.app-side {
  min-width: 0;
}

.app-filters {
  margin-bottom: var(--zh-size-regular);
}

.zh-slider__track {
  position: relative;
  height: var(--zh-size-tiny);
  background: var(--zh-black-15);
  margin-bottom: var(--zh-size-small-regular);
}

.zh-slider__fill {
  position: absolute;
  inset-block: 0;
  background: var(--zh-color-accent);
  left: 0;
  right: 0;
}

.zh-slider__inputs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--zh-size-small-regular);
}

.zh-quickranges {
  display: flex;
  flex-wrap: wrap;
  gap: var(--zh-size-mini);
  margin-top: var(--zh-size-tiny);
}

#overlay-time-field {
  margin-top: var(--zh-size-tiny);
}

#overlay-time-output {
  display: block;
  font-weight: 900;
}

/* ---- Result list ---- */
.app-results {
  min-width: 0;
}

.app-result-list {
  display: grid;
  gap: var(--zh-size-small-regular);
  margin: 0 0 var(--zh-size-regular);
  padding: 0;
  list-style: none;
}

.zh-result {
  display: grid;
  grid-template-columns: 84px minmax(0, 1fr);
  gap: var(--zh-size-small-regular);
