/**
 * Small DOM/format helpers shared by the optional app modules.
 * No framework, no dependencies (see coordination/README.md D2/D4).
 */

/** Create an element: el('div', { class: 'x' }, [child, 'text']). */
export function el(tag, attrs = {}, children = []) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    if (value === null || value === undefined || value === false) continue;
    if (key === 'class') node.className = value;
    else if (key === 'dataset') Object.assign(node.dataset, value);
    else if (key === 'html') node.innerHTML = value;
    else if (key === 'text') node.textContent = value;
    else if (key.startsWith('on') && typeof value === 'function') node.addEventListener(key.slice(2), value);
    else node.setAttribute(key, String(value));
  }
  for (const child of [].concat(children)) {
    if (child === null || child === undefined || child === false) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

export const qs = (selector, root = document) => root.querySelector(selector);
export const qsa = (selector, root = document) => Array.from(root.querySelectorAll(selector));

/** Escape text for use in an HTML string (only where innerHTML is required). */
export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/** Year or year range, honest about missing values. */
export function formatYear(year) {
  if (year === null || year === undefined || Number.isNaN(Number(year))) return 'ohne Jahr';
  const n = Number(year);
  return n < 0 ? `${Math.abs(n)} v. Chr.` : String(n);
}

export function formatYearRange(start, end) {
  if (start && end && start !== end) return `${formatYear(start)}–${formatYear(end)}`;
  return formatYear(start ?? end);
}

export function debounce(fn, wait = 250) {
  let timer;
  const wrapped = (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), wait);
  };
  wrapped.cancel = () => clearTimeout(timer);
  wrapped.flush = (...args) => {
    clearTimeout(timer);
    fn(...args);
  };
  return wrapped;
}

export function throttle(fn, wait = 100) {
  let last = 0;
  let timer;
  return (...args) => {
    const now = Date.now();
    const remaining = wait - (now - last);
    if (remaining <= 0) {
      last = now;
      fn(...args);
    } else if (!timer) {
      timer = setTimeout(() => {
        timer = undefined;
        last = Date.now();
        fn(...args);
      }, remaining);
    }
  };
}

/** Set state text on an element that is always in the accessibility tree. */
export function setStatus(node, message, kind = 'info') {
  if (!node) return;
  node.textContent = message;
  node.dataset.kind = kind;
}

/** Minimal focus trap for the detail panel (Esc handled by the caller). */
export function trapFocus(container, event) {
  const focusables = qsa(
    'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
    container,
  ).filter((node) => node.offsetParent !== null || node === document.activeElement);
  if (focusables.length === 0) return;
  const first = focusables[0];
  const last = focusables[focusables.length - 1];
  if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus();
  } else if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus();
  }
}

/** Build an absolutised, shareable URL for the current state. */
export function permalink() {
  return window.location.href;
}

export async function copyText(text) {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    /* fall through to the legacy path */
  }
  try {
    const area = document.createElement('textarea');
    area.value = text;
    area.setAttribute('readonly', '');
    area.style.position = 'fixed';
    area.style.opacity = '0';
    document.body.append(area);
    area.select();
    const ok = document.execCommand('copy');
    area.remove();
    return ok;
  } catch {
    return false;
  }
}

/**
 * URL-backed application state + a tiny event bus (coordination/README.md D4).
 *
 *   const store = createStore({ defaults });
 *   store.getState()            -> { q, from, to, provider, type, place, lat, lon, zoom, selected, view, sort, overlay, otime }
 *   store.update({ from: 1800 }) -> merge, sync URL (replaceState), notify subscribers
 *   store.subscribe(fn)          -> fn(state, changedKeys); returns unsubscribe
 *
 *   const bus = createBus();
 *   bus.on('records:loaded', fn); bus.emit('records:loaded', { records });
 *
 * Everything is defensive: the module must also import cleanly in Node (tests)
 * where `window`/`history`/`location` may not exist.
 */

export const STATE_DEFAULTS = Object.freeze({
  q: '', // free-text filter over title/creator/place
  from: 1500, // publication year range filter
  to: 1900,
  provider: '', // providerId or '' for all
  type: '', // record type or '' for all
  place: '', // selected place label
  lat: 47.3769, // Zürich as the initial view (documented default, not a search result)
  lon: 8.5417,
  zoom: 12,
  selected: '', // record id
  view: 'split', // 'split' | 'map' | 'list'
  sort: 'year-asc',
  overlay: '', // swisstopo layer id of the comparison layer
  otime: '', // time value for that layer (YYYYMMDD where the layer is a Zeitreise layer)
});

/** URL parameter names kept short for shareable links. */
export const PARAM = {
  q: 'q',
  from: 'from',
  to: 'to',
  provider: 'p',
  type: 't',
  place: 'place',
  lat: 'lat',
  lon: 'lon',
  zoom: 'z',
  selected: 'sel',
  view: 'view',
  sort: 'sort',
  overlay: 'ov',
  otime: 'ot',
};

const TYPES = {
  string: ['q', 'provider', 'type', 'place', 'selected', 'view', 'sort', 'overlay', 'otime'],
  number: ['from', 'to', 'lat', 'lon', 'zoom'],
};

function coerce(key, value) {
  if (value === null || value === undefined || value === '') return STATE_DEFAULTS[key];
  if (TYPES.number.includes(key)) {
    const n = Number(value);
    return Number.isFinite(n) ? n : STATE_DEFAULTS[key];
  }
  return String(value);
}

function safeHistory() {
  try {
    if (typeof window === 'undefined') return null;
    return window.history && typeof window.history.replaceState === 'function' ? window.history : null;
  } catch {
    return null;
  }
}

function safeLocation() {
  try {
    if (typeof window === 'undefined') return null;
    return window.location || null;
  } catch {
    return null;
  }
}

export function readStateFromUrl(search = (safeLocation()?.search ?? ''), defaults = STATE_DEFAULTS) {
  const params = new URLSearchParams(search);
  const state = { ...defaults };
  for (const [key, param] of Object.entries(PARAM)) {
    if (params.has(param)) {
      const raw = params.get(param);
      state[key] = raw === '' ? defaults[key] : coerce(key, raw);
    }
  }
  return sanitise(state);
}

/** Keep numeric state inside sane bounds so a hand-written URL cannot break the UI. */
export function sanitise(state) {
  const out = { ...state };
  out.lat = Math.max(-85, Math.min(85, Number(out.lat) || STATE_DEFAULTS.lat));
  out.lon = ((((Number(out.lon) || STATE_DEFAULTS.lon) + 180) % 360) + 360) % 360 - 180;
  out.zoom = Math.max(2, Math.min(18, Number(out.zoom) || STATE_DEFAULTS.zoom));
  const from = Number.isFinite(Number(out.from)) ? Number(out.from) : STATE_DEFAULTS.from;
  const to = Number.isFinite(Number(out.to)) ? Number(out.to) : STATE_DEFAULTS.to;
  out.from = Math.min(from, to);
  out.to = Math.max(from, to);
  if (!['split', 'map', 'list'].includes(out.view)) out.view = STATE_DEFAULTS.view;
  if (!['year-asc', 'year-desc', 'title'].includes(out.sort)) out.sort = STATE_DEFAULTS.sort;
  out.q = String(out.q || '').slice(0, 200);
  out.place = String(out.place || '').slice(0, 200);
  return out;
}

export function stateToQuery(state, defaults = STATE_DEFAULTS) {
  const params = new URLSearchParams();
  const current = sanitise({ ...defaults, ...state });
  for (const [key, param] of Object.entries(PARAM)) {
    const value = current[key];
    if (value === defaults[key]) continue;
    if (key === 'lat' || key === 'lon') params.set(param, Number(value).toFixed(4));
    else params.set(param, String(value));
  }
  return params.toString();
}

export function createBus() {
  const listeners = new Map();
  return {
    on(name, fn) {
      if (!listeners.has(name)) listeners.set(name, new Set());
      listeners.get(name).add(fn);
      return () => listeners.get(name)?.delete(fn);
    },
    off(name, fn) {
      listeners.get(name)?.delete(fn);
    },
    emit(name, detail) {
      for (const fn of listeners.get(name) ?? []) {
        try {
          fn(detail);
        } catch (err) {
          // A broken module must not take the app down.
          console.error(`[bus] listener for "${name}" failed`, err);
        }
      }
    },
  };
}

export function createStore({ initial = {}, defaults = STATE_DEFAULTS, history = safeHistory(), location = safeLocation() } = {}) {
  let state = sanitise({ ...defaults, ...initial, ...readStateFromUrl(location?.search ?? '', defaults) });
  const subscribers = new Set();
  let urlSync = Boolean(history && location);
  let pending = null;

  function notify(changedKeys) {
    for (const fn of subscribers) {
      try {
        fn(state, changedKeys);
      } catch (err) {
        console.error('[store] subscriber failed', err);
      }
    }
  }

  function syncUrl() {
    if (!urlSync || !history || !location) return;
    const query = stateToQuery(state, defaults);
    const next = `${location.pathname || '/'}${query ? `?${query}` : ''}`;
    try {
      history.replaceState({ ...state }, '', next);
    } catch {
      urlSync = false; // sandboxed iframe or file:// – keep working without URL sync
    }
  }

  function update(patch, { silent = false } = {}) {
    const changed = [];
    const next = { ...state };
    for (const [key, value] of Object.entries(patch)) {
      if (!(key in defaults)) continue;
      const coerced = coerce(key, value);
      if (next[key] !== coerced) {
        next[key] = coerced;
        changed.push(key);
      }
    }
    state = sanitise(next);
    if (changed.length === 0) return state;
    syncUrl();
    if (!silent) notify(changed);
    return state;
  }

  return {
    getState: () => state,
    update,
    subscribe(fn) {
      subscribers.add(fn);
      return () => subscribers.delete(fn);
    },
    /** Used by tests and by the "reset" action. */
    replace(next, options) {
      return update({ ...defaults, ...next }, options);
    },
    setUrlSync(enabled) {
      urlSync = Boolean(enabled);
    },
  };
}

/**
 * Data layer: load, validate, index, filter and sort the seed records.
 *
 * Files (see coordination/data-contract.md):
 *   /data/records.json   { generatedAt, method, records: [...] }
 *   /data/sources.json   { generatedAt, providers: [...] }
 *   /data/overlays.json  { generatedAt, overlays: [...] }   (swisstopo WMTS layers)
 *
 * The record schema is fixed by D4; this module is the only place that knows it.
 */

export const RECORDS_URL = '/data/records.json';
export const SOURCES_URL = '/data/sources.json';
export const OVERLAYS_URL = '/data/overlays.json';

const REQUIRED_STRING_FIELDS = ['id', 'title', 'providerId', 'institution', 'rights', 'recordUrl'];

export function validateRecord(record, index = -1) {
  const problems = [];
  if (!record || typeof record !== 'object') return [`record[${index}] is not an object`];
  for (const field of REQUIRED_STRING_FIELDS) {
    if (!record[field] || typeof record[field] !== 'string') problems.push(`${record.id ?? `record[${index}]`}: missing ${field}`);
  }
  if (record.id && !/^[a-z0-9-]+:.+$/.test(record.id)) problems.push(`${record.id}: id must be "<providerId>:<upstream id>"`);
  if (record.recordUrl && !/^https:\/\//.test(record.recordUrl)) problems.push(`${record.id}: recordUrl must be https`);
  if (!Number.isFinite(record.yearStart) || !Number.isFinite(record.yearEnd)) problems.push(`${record.id}: yearStart/yearEnd missing`);
  else if (record.yearStart > record.yearEnd) problems.push(`${record.id}: yearStart > yearEnd`);
  if (record.extent) {
    const { west, east, south, north } = record.extent;
    if (![west, east, south, north].every(Number.isFinite)) problems.push(`${record.id}: extent must be numeric`);
    else if (west >= east || south >= north) problems.push(`${record.id}: extent bounds inverted`);
  }
  if (record.overlay?.urlTemplate && !/^https:\/\//.test(record.overlay.urlTemplate)) {
    problems.push(`${record.id}: overlay.urlTemplate must be https`);
  }
  return problems;
}

/** Fetch + validate. Never throws: returns { records, errors, ok }. */
export async function loadRecords(fetchImpl = globalThis.fetch) {
  if (typeof fetchImpl !== 'function') return { records: [], errors: ['no fetch implementation'], ok: false };
  const res = await fetchImpl(RECORDS_URL, { headers: { accept: 'application/json' } });
  if (!res.ok) throw new Error(`${res.status} ${RECORDS_URL}`);
  const data = await res.json();
  const records = Array.isArray(data.records) ? data.records : [];
  const errors = records.flatMap((record, i) => validateRecord(record, i));
  return { records, errors, generatedAt: data.generatedAt ?? null, method: data.method ?? null, ok: errors.length === 0 };
}

export async function loadSources(fetchImpl = globalThis.fetch) {
  const res = await fetchImpl(SOURCES_URL, { headers: { accept: 'application/json' } });
  if (!res.ok) throw new Error(`${res.status} ${SOURCES_URL}`);
  const data = await res.json();
  return { providers: data.providers ?? [], generatedAt: data.generatedAt ?? null };
}

export async function loadOverlays(fetchImpl = globalThis.fetch) {
  const res = await fetchImpl(OVERLAYS_URL, { headers: { accept: 'application/json' } });
  if (!res.ok) throw new Error(`${res.status} ${OVERLAYS_URL}`);
  const data = await res.json();
  return { overlays: data.overlays ?? [], attribution: data.attribution ?? null, generatedAt: data.generatedAt ?? null };
}

export function indexRecords(records) {
  return new Map(records.map((record) => [record.id, record]));
}

/** Publication years available in the data (never invented). */
export function yearBounds(records) {
  const years = records.flatMap((r) => [r.yearStart, r.yearEnd]).filter(Number.isFinite);
  if (years.length === 0) return { min: 1500, max: new Date().getFullYear() };
  return { min: Math.min(...years), max: Math.max(...years) };
}

export function recordCenter(record) {
  if (record?.geo && Number.isFinite(record.geo.lat) && Number.isFinite(record.geo.lon)) {
    return { lat: record.geo.lat, lon: record.geo.lon };
  }
  const e = record?.extent;
  if (e && [e.west, e.east, e.south, e.north].every(Number.isFinite)) {
    return { lat: (e.south + e.north) / 2, lon: (e.west + e.east) / 2 };
  }
  return null;
}

export function titleText(record) {
  return [
    record.title,
    ...(record.titleAlt ?? []),
    ...(record.creators ?? []),
    record.institution,
    record.publisher,
    record.subjectPlace,
    record.shelfmark,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
}

export function matchesQuery(record, query) {
  const needle = String(query || '').trim().toLowerCase();
  if (!needle) return true;
  const haystack = titleText(record);
  return needle
    .split(/\s+/)
    .every((token) => haystack.includes(token));
}

export function overlapsRange(record, from, to) {
  const start = record.yearStart ?? record.yearEnd;
  const end = record.yearEnd ?? record.yearStart;
  if (!Number.isFinite(start) || !Number.isFinite(end)) return true;
  return start <= to && end >= from;
}

/** The shared filter pipeline (also used by the Worker-free tests). */
export function filterRecords(state, records) {
  const from = Number(state?.from ?? -Infinity);
  const to = Number(state?.to ?? Infinity);
  const provider = state?.provider || '';
  const type = state?.type || '';
  return records.filter(
    (record) =>
      matchesQuery(record, state?.q) &&
      overlapsRange(record, from, to) &&
      (!provider || record.providerId === provider) &&
      (!type || record.type === type),
  );
}

export function sortRecords(records, sort = 'year-asc') {
  const copy = [...records];
  if (sort === 'year-desc') copy.sort((a, b) => (b.yearStart ?? 0) - (a.yearStart ?? 0) || a.title.localeCompare(b.title, 'de'));
  else if (sort === 'title') copy.sort((a, b) => a.title.localeCompare(b.title, 'de'));
  else copy.sort((a, b) => (a.yearStart ?? 0) - (b.yearStart ?? 0) || a.title.localeCompare(b.title, 'de'));
  return copy;
}

export function bboxIntersects(a, b) {
  if (!a || !b) return false;
  return a.west <= b.east && a.east >= b.west && a.south <= b.north && a.north >= b.south;
}

/** Records whose point or bbox lies inside the current map view. */
export function recordsInBounds(records, bounds) {
  if (!bounds) return records;
  return records.filter((record) => {
    const center = recordCenter(record);
    if (record.extent && bboxIntersects(record.extent, bounds)) return true;
    if (!center) return false;
    return center.lat >= bounds.south && center.lat <= bounds.north && center.lon >= bounds.west && center.lon <= bounds.east;
  });
}

export function facets(records) {
  const providers = new Map();
  const types = new Map();
  for (const record of records) {
    providers.set(record.providerId, (providers.get(record.providerId) ?? 0) + 1);
    types.set(record.type ?? 'map', (types.get(record.type ?? 'map') ?? 0) + 1);
  }
  return { providers, types };
}

export function extentUnion(records) {
  const boxes = records.map((r) => r.extent).filter(Boolean);
  if (boxes.length === 0) return null;
  return {
    west: Math.min(...boxes.map((b) => b.west)),
    east: Math.max(...boxes.map((b) => b.east)),
    south: Math.min(...boxes.map((b) => b.south)),
    north: Math.max(...boxes.map((b) => b.north)),
  };
}

/**
 * Bootstrap for Kartenzeit. Loads the data, wires the optional UI modules and
 * degrades gracefully when one of them is missing (coordination D4).
 */

import { createBus, createStore } from './store.js';
import { el, qs, formatYearRange } from './dom.js';
import { loadOverlays, loadRecords, loadSources, yearBounds } from './records.js';

const bus = createBus();
const store = createStore();

const ctx = {
  store,
  bus,
  dom: { el, qs },
  data: {
    records: [],
    sources: [],
    overlays: [],
    recordIndex: new Map(),
    years: { min: 1500, max: 1900 },
    loadErrors: [],
  },
};

const optionalModules = [
  ['map', './map.js'],
  ['search', './search.js'],
  ['results', './results.js'],
  ['detail', './detail.js'],
];

async function initModules() {
  const loaded = [];
  for (const [name, specifier] of optionalModules) {
    try {
      const module = await import(specifier);
      if (typeof module.init === 'function') {
        await module.init(ctx);
        loaded.push(name);
      }
    } catch (err) {
      // A missing/failing module must not stop the rest of the app.
      console.warn(`[kartenzeit] module "${name}" not available`, err);
    }
  }
  ctx.modules = loaded;
  bus.emit('app:ready', ctx);
}

function renderIntro() {
  const count = qs('#intro-count');
  if (count) count.textContent = `${ctx.data.records.length} Datensätze`;
  const tagList = qs('#intro-tags');
  if (tagList) {
    tagList.replaceChildren(
      ...ctx.data.sources.map((source) =>
        el('li', {}, [el('span', { class: 'zh-tag zh-tag--blue', text: source.name?.split('–')[0]?.trim() || source.id })]),
      ),
      el('li', {}, [el('span', { class: 'zh-tag zh-tag--turquoise', text: `${ctx.data.overlays.length} swisstopo-Kartenwerke` })]),
    );
  }
  const sourceList = qs('#source-list');
  if (sourceList) {
    const entries = [];
    for (const source of ctx.data.sources) {
      entries.push(el('dt', { text: source.name || source.id }));
      entries.push(
        el('dd', {}, [
          source.attribution ? el('span', { text: `${source.attribution}. ` }) : null,
          source.rights ? el('span', { text: `${source.rights} ` }) : null,
          source.homepage ? el('a', { href: source.homepage, rel: 'noopener', text: source.homepage.replace(/^https?:\/\//, '') }) : null,
          source.api?.oai ? el('div', { html: `<small>OAI-PMH: <code>${source.api.oai.split(' ')[0]}</code></small>` }) : null,
        ]),
      );
    }
    sourceList.replaceChildren(...entries);
  }
  const state = qs('#results-state');
  if (state && ctx.data.loadErrors.length > 0) {
    state.hidden = false;
    state.className = 'zh-state zh-state--error';
    state.textContent = `Datenprüfung: ${ctx.data.loadErrors.length} Feld(er) unvollständig – bitte Quellenregister prüfen.`;
  }
}

async function main() {
  document.documentElement.dataset.app = 'kartenzeit';

  // Data first: every module can rely on ctx.data being populated.
  try {
    const [{ records, errors, generatedAt }, sources, overlays] = await Promise.all([loadRecords(), loadSources(), loadOverlays()]);
    ctx.data.records = records;
    ctx.data.sources = sources.providers;
    ctx.data.overlays = overlays.overlays;
    ctx.data.recordIndex = new Map(records.map((r) => [r.id, r]));
    ctx.data.years = yearBounds(records);
    ctx.data.generatedAt = generatedAt;
    ctx.data.loadErrors = errors;
    bus.emit('records:loaded', { records, sources: sources.providers, overlays: overlays.overlays });
  } catch (err) {
    console.error('[kartenzeit] data load failed', err);
    const state = qs('#results-state') || qs('#map-fallback');
    if (state) {
      state.hidden = false;
      state.className = 'zh-state zh-state--error';
      state.replaceChildren(
        el('span', { class: 'zh-state__title', text: 'Die Datensätze konnten nicht geladen werden.' }),
        el('span', { text: `Grund: ${err?.message || err}. Bitte die Seite neu laden; die Rohdaten liegen unter /data/records.json.` }),
      );
    }
    bus.emit('records:error', { error: err });
    return; // still initialise modules so the map/search part is usable
  }

  renderIntro();
  await initModules();

  // Diagnostics for the console and for curious users of the API.
  console.info(
    `[kartenzeit] ${ctx.modules?.length ?? 0} Modul(e): ${(ctx.modules ?? []).join(', ')} · ` +
      `${ctx.data.records.length} Datensätze · ${ctx.data.overlays.length} Kartenwerke (${ctx.data.generatedAt ?? 'ohne Datum'})`,
  );
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    main().catch((err) => console.error('[kartenzeit] startup failed', err));
  });
} else {
  main().catch((err) => console.error('[kartenzeit] startup failed', err));
}

export { bus, store, ctx, main };

/**
 * Interactive map: a dependency-free slippy map (Web Mercator, 256 px tiles)
 * fed by swisstopo WMTS geoservices, plus historical comparison layers.
 *
 * Deliberately small and explicit instead of vendoring a whole map library:
 *   - base: Landeskarte (swisstopo `ch.swisstopo.pixelkarte-farbe`)
 *   - comparison: any layer from /data/overlays.json (Zeitreise, Dufour, Siegfried, …)
 *   - markers: records with a documented point/bbox (public/app/records.js)
 *
 * Keyboard: the container is focusable; arrows pan, +/- zoom, Home = Zürich,
 * End = fit results. The result list is the equivalent accessible interface.
 */

import { debounce, el, qs } from './dom.js';
import { recordCenter } from './records.js';

const TILE = 256;

/** Base map: documented swisstopo WMTS tile template (CORS `*`, OGD). */
export const BASE_LAYER = {
  id: 'ch.swisstopo.pixelkarte-farbe',
  title: 'Landeskarte (swisstopo)',
  urlTemplate:
    'https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.pixelkarte-farbe/default/current/3857/{TileMatrix}/{TileCol}/{TileRow}.jpeg',
  maxZoom: 18,
  attribution: '© swisstopo – Landeskarte',
};

export const ZURICH = { lat: 47.3769, lon: 8.5417, zoom: 12 };
export const SWITZERLAND = { west: 5.140242, east: 11.47757, south: 45.398181, north: 48.230651 };

export const lonToTileX = (lon, z) => ((lon + 180) / 360) * 2 ** z;
export const latToTileY = (lat, z) => {
  const s = Math.sin((Math.max(-85.05112878, Math.min(85.05112878, lat)) * Math.PI) / 180);
  return (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * 2 ** z;
};
export const tileXToLon = (x, z) => (x / 2 ** z) * 360 - 180;
export const tileYToLat = (y, z) => {
  const n = Math.PI - (2 * Math.PI * y) / 2 ** z;
  return (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
};

/** Tile URL from a WMTS template with {TileMatrix}/{TileCol}/{TileRow}/{Time}. */
export function tileUrl(template, { z, x, y, time }) {
  return template
    .replace('{TileMatrix}', String(z))
    .replace('{TileCol}', String(x))
    .replace('{TileRow}', String(y))
    .replace('{Time}', encodeURIComponent(time ?? 'current'));
}

export function init(ctx) {
  const container = qs('[data-map]');
  if (!container) return;

  // The shell ships a <noscript>/fallback box; the real map replaces it.
  const fallback = qs('#map-fallback');
  if (fallback) fallback.remove();

  const state = {
    lat: ctx.store.getState().lat,
    lon: ctx.store.getState().lon,
    zoom: Math.round(ctx.store.getState().zoom),
    overlay: null,
    overlayTime: null,
    records: [],
    filtered: [],
    selected: '',
  };

  container.setAttribute('tabindex', '0');
  container.setAttribute('role', 'application');
  container.setAttribute('aria-label', 'Interaktive Karte historischer Karten; Pfeiltasten verschieben, Plus und Minus zoomen');

  const baseLayer = el('div', { class: 'map-layer map-layer--base', 'aria-hidden': 'true' });
  const overlayLayer = el('div', { class: 'map-layer map-layer--overlay', 'aria-hidden': 'true' });
  const shapeLayer = el('div', { class: 'map-layer map-layer--shapes', 'aria-hidden': 'true' });
  const markerLayer = el('div', { class: 'map-layer map-layer--markers' });
  const live = el('p', { class: 'visuallyhidden', role: 'status', 'aria-live': 'polite' });
  const badge = el('div', { class: 'map-badge' });
  const controls = el('div', { class: 'map-controls' }, [
    el('button', { class: 'zh-button zh-button--small', type: 'button', title: 'Hineinzoomen', 'aria-label': 'Hineinzoomen', onclick: () => zoomBy(1) }, ['+']),
    el('button', { class: 'zh-button zh-button--small', type: 'button', title: 'Herauszoomen', 'aria-label': 'Herauszoomen', onclick: () => zoomBy(-1) }, ['−']),
  ]);

  container.replaceChildren(baseLayer, overlayLayer, shapeLayer, markerLayer, controls, badge, live);

  const cache = new Map(); // tile key -> <img>
  const markers = new Map(); // record id -> <button>

  function templateFor(layer, time) {
    return layer.urlTemplate.replace('{Time}', encodeURIComponent(time ?? layer.timeValues?.[0] ?? 'current'));
  }

  function render() {
    const w = container.clientWidth || 640;
    const h = container.clientHeight || 420;
    const z = state.zoom;
    const scale = 2 ** z;
    const centerX = lonToTileX(state.lon, z) * TILE;
    const centerY = latToTileY(state.lat, z) * TILE;
    const originX = centerX - w / 2;
    const originY = centerY - h / 2;

    renderTiles(baseLayer, cache, 'base', BASE_LAYER.urlTemplate, null, originX, originY, w, h, z, scale);
    if (state.overlay) {
      renderTiles(overlayLayer, cache, `ov:${state.overlay.id}`, state.overlay.urlTemplate, state.overlayTime, originX, originY, w, h, z, scale);
    } else {
      overlayLayer.replaceChildren();
    }
    renderMarkers(originX, originY, w, h, z);
    renderExtent(originX, originY, z);
    updateBadge();
    updateLive();
  }

  function renderTiles(layerEl, tileCache, kind, template, time, originX, originY, w, h, z, scale) {
    const maxZoom = kind === 'base' ? BASE_LAYER.maxZoom : Number(state.overlay?.maxZoom ?? 18);
    const tileZ = Math.min(z, maxZoom);
    const visible = new Set();
    const x0 = Math.floor(originX / TILE);
    const x1 = Math.floor((originX + w - 1) / TILE);
    const y0 = Math.max(0, Math.floor(originY / TILE));
    const y1 = Math.min(scale - 1, Math.floor((originY + h - 1) / TILE));

    for (let x = x0; x <= x1; x += 1) {
      const wrapped = ((x % scale) + scale) % scale;
      for (let y = y0; y <= y1; y += 1) {
        const key = `${kind}/${tileZ}/${wrapped}/${y}`;
        visible.add(key);
        let img = tileCache.get(key);
        if (!img) {
          img = document.createElement('img');
          img.className = kind === 'base' ? 'map-tile' : 'map-tile map-overlay-tile';
          img.alt = '';
          img.decoding = 'async';
          img.src = tileUrl(template, { z: tileZ, x: wrapped, y, time });
          img.addEventListener('error', () => {
            img.dataset.failed = 'true';
            img.style.visibility = 'hidden';
          });
          tileCache.set(key, img);
          layerEl.append(img);
          // keep the cache bounded
          if (tileCache.size > 240) {
            const [oldKey, oldImg] = tileCache.entries().next().value;
            if (oldKey !== key) {
              oldImg.remove();
              tileCache.delete(oldKey);
            }
          }
        }
        img.style.transform = `translate3d(${x * TILE - originX}px, ${y * TILE - originY}px, 0)`;
      }
    }
    // Drop tiles that scrolled out of view for this layer kind.
    for (const [key, img] of tileCache) {
      if (!key.startsWith(`${kind}/`)) continue;
      if (!visible.has(key) && img.parentElement === layerEl && tileCache.size > 60) {
        img.remove();
        tileCache.delete(key);
      }
    }
  }

  function renderMarkers(originX, originY, w, h, z) {
    const wanted = new Set();
    state.filtered.slice(0, 300).forEach((record, index) => {
      const center = recordCenter(record);
      if (!center) return;
      const x = lonToTileX(center.lon, z) * TILE - originX;
      const y = latToTileY(center.lat, z) * TILE - originY;
      if (x < -40 || y < -40 || x > w + 40 || y > h + 40) return;
      wanted.add(record.id);
      let marker = markers.get(record.id);
      if (!marker) {
        marker = el('button', {
          class: 'map-marker',
          type: 'button',
          onclick: () => {
            ctx.store.update({ selected: record.id });
            ctx.bus.emit('record:selected', { record, source: 'map' });
          },
        });
        markers.set(record.id, marker);
        markerLayer.append(marker);
      }
      marker.textContent = String(index + 1);
      marker.dataset.id = record.id;
      marker.title = record.title;
      marker.setAttribute('aria-label', `${index + 1}. ${record.title} – Details öffnen`);
      marker.classList.toggle('is-selected', state.selected === record.id);
      marker.style.transform = `translate3d(${x}px, ${y}px, 0)`;
    });
    for (const [id, marker] of markers) {
      if (!wanted.has(id)) {
        marker.remove();
        markers.delete(id);
      }
    }
  }

  function renderExtent(originX, originY, z) {
    shapeLayer.replaceChildren();
    const record = ctx.data.recordIndex?.get(state.selected) ?? state.records.find((r) => r.id === state.selected);
    if (!record?.extent) return;
    const { west, east, south, north } = record.extent;
    const x1 = lonToTileX(west, z) * TILE - originX;
    const x2 = lonToTileX(east, z) * TILE - originX;
    const y1 = latToTileY(north, z) * TILE - originY;
    const y2 = latToTileY(south, z) * TILE - originY;
    if (![x1, x2, y1, y2].every(Number.isFinite) || x2 - x1 > container.clientWidth * 200) return;
    shapeLayer.append(
      el('div', {
        class: 'map-extent',
        style: `left:${Math.min(x1, x2)}px; top:${Math.min(y1, y2)}px; width:${Math.abs(x2 - x1)}px; height:${Math.abs(y2 - y1)}px`,
      }),
    );
  }

  function updateBadge() {
    const items = [
      el('span', { class: 'zh-tag', text: BASE_LAYER.attribution }),
      state.overlay ? el('span', { class: 'zh-tag zh-tag--solid', text: `${state.overlay.title}${state.overlayTime ? ` · ${formatTime(state.overlayTime)}` : ''}` }) : null,
    ].filter(Boolean);
    badge.replaceChildren(...items);
    const extra = qs('#map-attribution-extra');
    if (extra) {
      extra.textContent = state.overlay
        ? `Ebene: ${state.overlay.title} (${state.overlay.attribution ?? '© swisstopo'})`
        : '';
    }
  }

  function updateLive() {
    live.textContent = `Kartenausschnitt: ${state.lat.toFixed(3)}° N, ${state.lon.toFixed(3)}° O, Zoomstufe ${state.zoom}.`;
  }

  const push = debounce(() => {
    ctx.store.update({ lat: state.lat, lon: state.lon, zoom: state.zoom });
    ctx.bus.emit('map:moved', { lat: state.lat, lon: state.lon, zoom: state.zoom, bounds: currentBounds() });
  }, 220);

  function currentBounds() {
    const w = container.clientWidth || 640;
    const h = container.clientHeight || 420;
    const scale = 2 ** state.zoom;
    const cx = lonToTileX(state.lon, state.zoom);
    const cy = latToTileY(state.lat, state.zoom);
    return {
      west: tileXToLon(cx - w / 2 / TILE, state.zoom),
      east: tileXToLon(cx + w / 2 / TILE, state.zoom),
      north: tileYToLat(cy - h / 2 / TILE, state.zoom),
      south: tileYToLat(cy + h / 2 / TILE, state.zoom),
    };
  }

  function zoomBy(delta, clientX, clientY) {
    const next = Math.max(2, Math.min(18, state.zoom + delta));
    if (next === state.zoom) return;
    if (clientX === undefined) {
      state.zoom = next;
    } else {
      // Keep the geo position under the cursor stable.
      const rect = container.getBoundingClientRect();
      const w = rect.width;
      const h = rect.height;
      const cx = lonToTileX(state.lon, state.zoom) * TILE;
      const cy = latToTileY(state.lat, state.zoom) * TILE;
      const offsetX = clientX - rect.left - w / 2;
      const offsetY = clientY - rect.top - h / 2;
      const lonAtCursor = tileXToLon((cx + offsetX) / TILE, state.zoom);
      const latAtCursor = tileYToLat((cy + offsetY) / TILE, state.zoom);
      state.zoom = next;
      const ncx = lonToTileX(lonAtCursor, next) * TILE;
      const ncy = latToTileY(latAtCursor, next) * TILE;
      state.lon = tileXToLon((ncx - offsetX) / TILE, next);
      state.lat = tileYToLat((ncy - offsetY) / TILE, next);
    }
    render();
    push();
  }

  function panByPixels(dx, dy) {
    const cx = lonToTileX(state.lon, state.zoom) * TILE - dx;
    const cy = latToTileY(state.lat, state.zoom) * TILE - dy;
    state.lon = tileXToLon(cx / TILE, state.zoom);
    state.lat = tileYToLat(cy / TILE, state.zoom);
    render();
    push();
  }

  function fitBounds(bounds, { padding = 48, maxZoom = 15 } = {}) {
    if (!bounds) return;
    const w = container.clientWidth || 640;
    const h = container.clientHeight || 420;
    const lonSpan = Math.max(0.0005, bounds.east - bounds.west);
    const latSpan = Math.max(0.0005, bounds.north - bounds.south);
    const zx = Math.log2(((w - padding * 2) / TILE) * (360 / lonSpan));
    const zy = Math.log2(((h - padding * 2) / TILE) * (360 / latSpan));
    state.zoom = Math.max(2, Math.min(maxZoom, Math.min(18, Math.floor(Math.min(zx, zy)))));
    state.lat = Math.max(-85, Math.min(85, (bounds.south + bounds.north) / 2));
    state.lon = ((bounds.west + bounds.east) / 2 + 540) % 360 - 180;
    render();
    push();
  }

  function setOverlay(layer, time) {
    state.overlay = layer ?? null;
    state.overlayTime = time ?? null;
    render();
  }

  function formatTime(value) {
    const text = String(value);
    if (/^\d{8}$/.test(text)) return `${text.slice(6, 8)}.${text.slice(4, 6)}.${text.slice(0, 4)}`;
    if (/^\d{4}$/.test(text)) return text;
    return text === 'current' ? 'aktuell' : text;
  }

  /* ---------------- interaction ---------------- */

  let dragging = null;
  container.addEventListener('pointerdown', (event) => {
    if (event.target.closest('button, a, select, input')) return;
    if (event.button !== 0 && event.pointerType === 'mouse') return;
    dragging = { x: event.clientX, y: event.clientY };
    container.classList.add('is-dragging');
    container.setPointerCapture?.(event.pointerId);
  });
  container.addEventListener('pointermove', (event) => {
    if (!dragging) return;
    const dx = event.clientX - dragging.x;
    const dy = event.clientY - dragging.y;
    dragging = { x: event.clientX, y: event.clientY };
    const cx = lonToTileX(state.lon, state.zoom) * TILE - dx;
    const cy = latToTileY(state.lat, state.zoom) * TILE - dy;
    state.lon = tileXToLon(cx / TILE, state.zoom);
    state.lat = tileYToLat(cy / TILE, state.zoom);
    render();
    push();
  });
  const endDrag = () => {
    if (!dragging) return;
    dragging = null;
    container.classList.remove('is-dragging');
    push.flush();
  };
  container.addEventListener('pointerup', endDrag);
  container.addEventListener('pointercancel', endDrag);
  container.addEventListener('lostpointercapture', endDrag);

  container.addEventListener(
    'wheel',
    (event) => {
      event.preventDefault();
      zoomBy(event.deltaY < 0 ? 1 : -1, event.clientX, event.clientY);
    },
    { passive: false },
  );

  container.addEventListener('dblclick', (event) => {
    if (event.target.closest('button')) return;
    zoomBy(1, event.clientX, event.clientY);
  });

  container.addEventListener('keydown', (event) => {
    const step = event.shiftKey ? 160 : 60;
    const keys = {
      ArrowLeft: () => panByPixels(-step, 0),
      ArrowRight: () => panByPixels(step, 0),
      ArrowUp: () => panByPixels(0, -step),
      ArrowDown: () => panByPixels(0, step),
      '+': () => zoomBy(1),
      '=': () => zoomBy(1),
      '-': () => zoomBy(-1),
      _: () => zoomBy(-1),
      Home: () => {
        Object.assign(state, { ...ZURICH, zoom: 12 });
        render();
        push();
      },
      End: () => fitBounds(resultsBounds(), { maxZoom: 12 }),
    };
    const action = keys[event.key];
    if (!action) return;
    event.preventDefault();
    action();
  });

  for (const button of document.querySelectorAll('[data-map-cmd]')) {
    button.addEventListener('click', () => {
      const cmd = button.dataset.mapCmd;
      if (cmd === 'in') zoomBy(1);
      if (cmd === 'out') zoomBy(-1);
      if (cmd === 'zurich') {
        Object.assign(state, { ...ZURICH });
        state.zoom = 12;
        render();
        push();
      }
      if (cmd === 'fitswitzerland') fitBounds(SWITZERLAND, { maxZoom: 8 });
      if (cmd === 'fitresults') fitBounds(resultsBounds(), { maxZoom: 12 });
    });
  }

  const resultsBounds = () => {
    const boxes = state.filtered.map((r) => r.extent).filter(Boolean);
    if (boxes.length === 0) {
      const points = state.filtered.map(recordCenter).filter(Boolean);
      if (points.length === 0) return SWITZERLAND;
      return {
        west: Math.min(...points.map((p) => p.lon)) - 0.2,
        east: Math.max(...points.map((p) => p.lon)) + 0.2,
        south: Math.min(...points.map((p) => p.lat)) - 0.2,
        north: Math.max(...points.map((p) => p.lat)) + 0.2,
      };
    }
    return {
      west: Math.min(...boxes.map((b) => b.west)),
      east: Math.max(...boxes.map((b) => b.east)),
      south: Math.min(...boxes.map((b) => b.south)),
      north: Math.max(...boxes.map((b) => b.north)),
    };
  };

  /* ---------------- store / bus wiring ---------------- */

  ctx.store.subscribe((next, changed) => {
    const interesting = changed.filter((key) => ['lat', 'lon', 'zoom'].includes(key));
    if (interesting.length === 0) return;
    if (Math.abs(next.lat - state.lat) < 1e-6 && Math.abs(next.lon - state.lon) < 1e-6 && Math.round(next.zoom) === state.zoom) return;
    state.lat = next.lat;
    state.lon = next.lon;
    state.zoom = Math.round(next.zoom);
    render();
  });

  ctx.bus.on('records:loaded', ({ records }) => {
    state.records = records;
    render();
  });
  ctx.bus.on('records:filtered', ({ records }) => {
    state.filtered = records;
    render();
  });
  ctx.bus.on('record:selected', ({ record }) => {
    state.selected = record?.id ?? '';
    const center = recordCenter(record);
    if (center) {
      const rect = container.getBoundingClientRect();
      const x = lonToTileX(center.lon, state.zoom) * TILE - (lonToTileX(state.lon, state.zoom) * TILE - rect.width / 2);
      const y = latToTileY(center.lat, state.zoom) * TILE - (latToTileY(state.lat, state.zoom) * TILE - rect.height / 2);
      const margin = 60;
      if (x < margin || y < margin || x > rect.width - margin || y > rect.height - margin) {
        state.lat = center.lat;
        state.lon = center.lon;
        state.zoom = Math.max(state.zoom, 10);
        render();
        push();
        return;
      }
    }
    render();
  });
  ctx.bus.on('record:deselected', () => {
    state.selected = '';
    render();
  });
  ctx.bus.on('place:selected', ({ lat, lon, zoom }) => {
    state.lat = lat;
    state.lon = lon;
    state.zoom = Math.max(4, Math.min(18, Math.round(zoom ?? 12)));
    render();
    push.flush();
  });
  ctx.bus.on('overlay:changed', ({ layer, time }) => setOverlay(layer, time));
  ctx.bus.on('overlay:time', ({ time }) => {
    state.overlayTime = time;
    render();
  });
  ctx.bus.on('view:fit', ({ bounds }) => fitBounds(bounds, { maxZoom: 12 }));

  const resize = debounce(() => render(), 120);
  if (typeof ResizeObserver !== 'undefined') new ResizeObserver(resize).observe(container);
  else window.addEventListener('resize', resize);

  render();

  ctx.map = {
    render,
    fitBounds,
    zoomBy,
    setOverlay,
    getView: () => ({ ...state }),
    currentBounds,
    resultsBounds,
    baseLayer: BASE_LAYER,
  };
  return ctx.map;
}

/**
 * Place search (combobox) on top of the Worker-proxied swisstopo SearchServer.
 * Falls back to a local title search when the upstream is unreachable, and
 * always says which one answered.
 */

import { debounce, el, qs, setStatus } from './dom.js';
import { matchesQuery } from './records.js';

const MIN_CHARS = 2;
const QUICK = [
  { label: 'Zürich (ZH)', lat: 47.3769, lon: 8.5417, zoom: 12 },
  { label: 'Schweiz', lat: 46.8, lon: 8.23, zoom: 7 },
  { label: 'Basel (BS)', lat: 47.5596, lon: 7.5886, zoom: 12 },
  { label: 'Genf (GE)', lat: 46.2044, lon: 6.1432, zoom: 12 },
];

export function init(ctx) {
  const form = qs('#place-search');
  const input = qs('#place-input');
  const submit = qs('#place-submit');
  const list = qs('#place-suggestions');
  const status = qs('#place-status');
  if (!form || !input || !list) return;

  const state = { items: [], active: -1, controller: null, source: null };

  input.value = ctx.store.getState().place || '';
  renderQuickLinks();

  function renderQuickLinks() {
    if (!status) return;
    const wrap = el('span', { class: 'zh-quickranges', id: 'place-quick' }, [
      el('span', { class: 'zh-hint', text: 'Schnellauswahl: ' }),
      ...QUICK.map((place) =>
        el('button', {
          class: 'zh-chip',
          type: 'button',
          onclick: () => choose({ ...place, origin: 'Schnellauswahl' }, { zoom: place.zoom }),
        }, [place.label]),
      ),
    ]);
    status.after(wrap);
    document.querySelector('#place-quick')?.replaceWith(wrap);
  }

  function close() {
    list.hidden = true;
    list.replaceChildren();
    state.items = [];
    state.active = -1;
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
  }

  function open(items, source) {
    state.items = items;
    state.source = source;
    state.active = items.length > 0 ? 0 : -1;
    list.replaceChildren(
      ...items.map((item, index) =>
        el('li', { role: 'none' }, [
          el(
            'button',
            {
              type: 'button',
              role: 'option',
              id: `place-option-${index}`,
              'aria-selected': index === 0 ? 'true' : 'false',
              onclick: () => choose(item),
              onmousemove: () => setActive(index),
            },
            [
              el('span', { text: item.label }),
              el('span', { class: 'zh-suggestions__type', text: item.origin ? item.origin.replace(/^gg25$/, 'swisstopo') : source }),
            ],
          ),
        ]),
      ),
    );
    list.hidden = items.length === 0;
    input.setAttribute('aria-expanded', items.length > 0 ? 'true' : 'false');
    updateActive();
  }

  function setActive(index) {
    state.active = index;
    for (const [i, node] of [...list.querySelectorAll('button')].entries()) {
      const selected = i === index;
      node.setAttribute('aria-selected', selected ? 'true' : 'false');
      if (selected) input.setAttribute('aria-activedescendant', node.id);
    }
  }

  function updateActive() {
    if (state.active >= 0) setActive(state.active);
    else input.removeAttribute('aria-activedescendant');
  }

  function choose(place, { zoom } = {}) {
    const targetZoom = zoom ?? zoomForBbox(place.bbox) ?? 12;
    input.value = place.label;
    ctx.store.update({ place: place.label, lat: place.lat, lon: place.lon, zoom: targetZoom });
    ctx.bus.emit('place:selected', { ...place, zoom: targetZoom, source: state.source });
    setStatus(status, `Kartenausschnitt auf „${place.label}“ gesetzt (${place.lat.toFixed(4)}, ${place.lon.toFixed(4)}).`);
    close();
  }

  function zoomForBbox(bbox) {
    if (!bbox) return null;
    const span = Math.max(bbox.east - bbox.west, bbox.north - bbox.south);
    if (!Number.isFinite(span) || span <= 0) return 14;
    if (span > 20) return 4;
    if (span > 5) return 7;
    if (span > 1) return 9;
    if (span > 0.25) return 11;
    if (span > 0.05) return 13;
    return 15;
  }

  function localFallback(query) {
    const records = ctx.data.records.filter((record) => matchesQuery(record, query)).slice(0, 6);
    if (records.length === 0) return [];
    return records.map((record) => ({
      label: record.title.length > 80 ? `${record.title.slice(0, 77)}…` : record.title,
      origin: 'Datensatz',
      lat: record.geo?.lat ?? null,
      lon: record.geo?.lon ?? null,
      bbox: record.extent ?? null,
      recordId: record.id,
    }));
  }

  async function suggest(query) {
    state.controller?.abort();
    state.controller = new AbortController();
    setStatus(status, 'Orte werden gesucht …');
    try {
      const res = await fetch(`/api/search/places?q=${encodeURIComponent(query)}&limit=8`, { signal: state.controller.signal });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      const items = (data.results ?? []).filter((item) => item.lat !== null && item.lon !== null);
      if (items.length === 0) {
        const local = localFallback(query);
        open(local, 'lokal');
        setStatus(status, local.length > 0 ? 'Kein Ort gefunden – Titelvorschläge aus den Datensätzen:' : 'Kein Ort und kein Titeltreffer gefunden.');
        return;
      }
      open(items, data.source ?? 'swisstopo');
      setStatus(status, `${items.length} Ortsvorschläge (swisstopo). Mit ↓/↑ wählen, Enter bestätigen.`);
    } catch (err) {
      if (err?.name === 'AbortError') return;
      const local = localFallback(query);
      open(local, 'lokal');
      setStatus(
        status,
        local.length > 0
          ? `Ortssuche nicht erreichbar (${err.message}) – Vorschläge aus den Datensätzen.`
          : `Ortssuche derzeit nicht erreichbar (${err.message}).`,
      );
    }
  }

  const onInput = debounce(() => {
    const query = input.value.trim();
    if (query.length < MIN_CHARS) {
      close();
      setStatus(status, 'Mindestens zwei Zeichen eingeben – oder eine Schnellauswahl nutzen.');
      return;
    }
    suggest(query);
  }, 260);

  input.addEventListener('input', onInput);
  input.addEventListener('keydown', (event) => {
    if (event.key === 'ArrowDown' && !list.hidden) {
      event.preventDefault();
      setActive(Math.min(state.items.length - 1, state.active + 1));
    } else if (event.key === 'ArrowUp' && !list.hidden) {
      event.preventDefault();
      setActive(Math.max(0, state.active - 1));
    } else if (event.key === 'Enter') {
      if (!list.hidden && state.active >= 0 && state.items[state.active]) {
        event.preventDefault();
        choose(state.items[state.active]);
      } else {
        event.preventDefault();
        onInput.flush();
      }
    } else if (event.key === 'Escape') {
      close();
    }
  });

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    if (!list.hidden && state.items[state.active]) {
      choose(state.items[state.active]);
      return;
    }
    const query = input.value.trim();
    if (query.length >= MIN_CHARS) onInput.flush();
  });

  document.addEventListener('click', (event) => {
    if (!form.contains(event.target)) close();
  });

  submit?.setAttribute('type', 'submit');

  // Keep the field in sync when another module changes the place (e.g. reset).
  ctx.store.subscribe((next, changed) => {
    if (changed.includes('place') && next.place && next.place !== input.value) input.value = next.place;
  });

  return { suggest, choose };
}

/**
 * Filters (time, collection, type, keyword), the comparison-layer picker and
 * the result list. Emits `records:filtered` so the map stays in sync.
 */

import { debounce, el, formatYearRange, qs, setStatus } from './dom.js';
import { facets, filterRecords, sortRecords } from './records.js';

const TYPE_LABELS = {
  map: 'Einzelkarte',
  atlas: 'Atlas / Kartenwerk',
  sheet: 'Kartenblatt',
  overlay: 'Georeferenzierte Ebene',
};

const SCALE_MAX = 1000; // slider resolution for the year range

export function init(ctx) {
  const listEl = qs('#result-list');
  const stateEl = qs('#results-state');
  const countEl = qs('#result-count');
  const liveEl = qs('#results-live');
  const sortEl = qs('#sort-select');
  const textEl = qs('#text-filter');
  const yearFrom = qs('#year-from');
  const yearTo = qs('#year-to');
  const yearFill = qs('#year-fill');
  const providerWrap = qs('#provider-filters');
  const typeWrap = qs('#type-filters');
  const overlayEl = qs('#overlay-select');
  const overlayTimeWrap = qs('#overlay-time-field');
  const overlayTime = qs('#overlay-time');
  const overlayTimeOut = qs('#overlay-time-output');
  const overlayNote = qs('#overlay-note');
  const resetEl = qs('#reset-filters');

  if (!listEl || !countEl) return;

  const records = ctx.data.records;
  const years = ctx.data.years;
  const { providers, types } = facets(records);
  let lastFiltered = [];

  /* ---------- controls ---------- */

  const setYearBounds = () => {
    if (yearFrom) {
      yearFrom.min = String(years.min);
      yearFrom.max = String(years.max);
    }
    if (yearTo) {
      yearTo.min = String(years.min);
      yearTo.max = String(years.max);
    }
    for (const chip of document.querySelectorAll('[data-range]')) {
      chip.addEventListener('click', () => {
        const value = chip.dataset.range;
        if (value === 'all') ctx.store.update({ from: years.min, to: years.max });
        else {
          const [from, to] = value.split('-').map(Number);
          ctx.store.update({ from, to });
        }
      });
    }
  };

  const buildCheckboxes = (wrap, entries, key) => {
    if (!wrap) return;
    wrap.replaceChildren(
      ...[...entries.entries()].map(([value, count]) => {
        const id = `${key}-${value}`;
        const input = el('input', {
          type: 'checkbox',
          id,
          value,
          onchange: () => ctx.store.update({ [key === 'providers' ? 'provider' : 'type']: input.checked ? value : '' }),
        });
        input.checked = (key === 'providers' ? ctx.store.getState().provider : ctx.store.getState().type) === value;
        return el('label', { class: 'zh-check', for: id }, [input, el('span', { text: `${value} (${count})` })]);
      }),
    );
  };

  buildCheckboxes(providerWrap, providers, 'providers');
  buildCheckboxes(typeWrap, types, 'types');

  sortEl?.addEventListener('change', () => ctx.store.update({ sort: sortEl.value }));
  textEl?.addEventListener(
    'input',
    debounce(() => ctx.store.update({ q: textEl.value.trim() }), 200),
  );
  const commitYears = debounce((patch) => ctx.store.update(patch), 250);
  yearFrom?.addEventListener('input', () => commitYears({ from: clampYear(yearFrom.value, years) }));
  yearTo?.addEventListener('input', () => commitYears({ to: clampYear(yearTo.value, years) }));

  resetEl?.addEventListener('click', () => {
    ctx.store.update({ from: years.min, to: years.max, provider: '', type: '', q: '', selected: '', overlay: '', otime: '' });
  });

  /* ---------- comparison layers (swisstopo WMTS) ---------- */

  const layers = ctx.data.overlays ?? [];
  const isHistorical = (layer) => /zeitreihen|hiks/.test(layer.id);
  if (overlayEl && layers.length > 0) {
    const historical = layers.filter(isHistorical).sort((a, b) => a.title.localeCompare(b.title, 'de'));
    const modern = layers.filter((l) => !isHistorical(l)).sort((a, b) => a.title.localeCompare(b.title, 'de'));
    overlayEl.replaceChildren(
      el('option', { value: '', text: 'keine Ebene' }),
      el('optgroup', { label: 'Historische Kartenwerke (Zeitreise, Dufour, Siegfried)' }, historical.map((l) => el('option', { value: l.id, text: l.title }))),
      el('optgroup', { label: 'Moderne Landeskarten' }, modern.map((l) => el('option', { value: l.id, text: l.title }))),
    );
    overlayEl.addEventListener('change', () => {
      const layer = layers.find((l) => l.id === overlayEl.value) ?? null;
      ctx.store.update({ overlay: layer?.id ?? '', otime: layer?.timeValues?.[0] ?? '' });
      applyOverlay(layer, layer?.timeValues?.[0]);
    });
  }

  function applyOverlay(layer, time) {
    if (!layer) {
      ctx.bus.emit('overlay:changed', { layer: null, time: null });
      if (overlayTimeWrap) overlayTimeWrap.hidden = true;
      if (overlayNote) overlayNote.textContent = 'Georeferenzierte Kartenwerke von swisstopo, direkt als Kachelebene über die moderne Grundkarte gelegt.';
      return;
    }
    const values = layer.timeValues ?? [];
    if (overlayTimeWrap && overlayTime && values.length > 1) {
      overlayTimeWrap.hidden = false;
      overlayTime.min = '0';
      overlayTime.max = String(values.length - 1);
      const index = Math.max(0, values.indexOf(time ?? ctx.store.getState().otime));
      overlayTime.value = String(index);
      updateTimeOutput(layer, values[index]);
    } else if (overlayTimeWrap) {
      overlayTimeWrap.hidden = true;
    }
    if (overlayNote) {
      overlayNote.textContent = `${layer.title} – ${values.length > 1 ? `${values.length} Ausgaben` : 'eine Ausgabe'}; ${
        layer.license ?? 'swisstopo geoservices'
      }.`;
    }
    ctx.bus.emit('overlay:changed', { layer, time: time ?? values[0] ?? 'current' });
  }

  function updateTimeOutput(layer, value) {
    if (!overlayTimeOut) return;
    overlayTimeOut.textContent = value ? `${formatTime(value)} (${layer.id})` : '';
  }

  overlayTime?.addEventListener(
    'input',
    debounce(() => {
      const layer = layers.find((l) => l.id === ctx.store.getState().overlay);
      const values = layer?.timeValues ?? [];
      const value = values[Number(overlayTime.value)];
      updateTimeOutput(layer, value);
      ctx.store.update({ otime: value ?? '' });
      ctx.bus.emit('overlay:time', { time: value, layer });
    }, 120),
  );

  function formatTime(value) {
    const text = String(value ?? '');
    if (/^\d{8}$/.test(text)) return `${text.slice(6, 8)}.${text.slice(4, 6)}.${text.slice(0, 4)}`;
    return text === 'current' ? 'aktuell' : text;
  }

  /* ---------- result list ---------- */

  function thumb(record) {
    const img = el('img', {
      class: 'zh-result__thumb',
      loading: 'lazy',
      decoding: 'async',
      alt: '',
      src: record.thumbnail,
    });
    img.addEventListener('error', () => {
      img.removeAttribute('src');
      img.classList.add('zh-result__thumb--missing');
      img.alt = 'Keine Vorschau verfügbar';
      img.replaceWith(el('span', { class: 'zh-result__thumb zh-result__thumb--missing', 'aria-hidden': 'true', text: '🗺' }));
    });
    return img;
  }

  function renderItem(record, index) {
    const button = el(
      'button',
      {
        class: 'zh-result',
        type: 'button',
        id: `result-${record.id.replace(/[^\w-]/g, '_')}`,
        'aria-current': ctx.store.getState().selected === record.id ? 'true' : 'false',
        onclick: () => select(record),
      },
      [
        thumb(record),
        el('span', { class: 'zh-result__body' }, [
          el('span', { class: 'zh-result__meta' }, [
            el('span', { class: 'zh-result__year', text: formatYearRange(record.yearStart, record.yearEnd) }),
            el('span', { text: showIndex(index) }),
            record.type ? el('span', { class: 'zh-tag', text: TYPE_LABELS[record.type] ?? record.type }) : null,
          ]),
          el('span', { class: 'zh-result__title', text: record.title }),
          el('span', { class: 'zh-result__meta' }, [
            el('span', { text: record.creators?.length ? record.creators.join(', ') : 'Urheber nicht angegeben' }),
          ]),
          el('span', { class: 'zh-result__meta' }, [
            el('span', { text: record.institution }),
            record.extent ? el('span', { class: 'zh-tag zh-tag--green', text: 'Kartenausschnitt bekannt' }) : el('span', { class: 'zh-tag', text: 'Ausschnitt nicht angegeben' }),
            record.iiifManifest ? el('span', { class: 'zh-tag zh-tag--turquoise', text: 'IIIF' }) : null,
          ]),
        ]),
      ],
    );
    return el('li', {}, [button]);
  }

  const showIndex = (index) => String(index + 1);

  function select(record) {
    ctx.store.update({ selected: record.id });
    ctx.bus.emit('record:selected', { record, source: 'list' });
  }

  let items = [];
  const render = debounce((filtered) => {
    lastFiltered = filtered;
    items = filtered;
    if (filtered.length === 0) {
      listEl.replaceChildren();
      if (stateEl) {
        stateEl.hidden = false;
        stateEl.className = 'zh-state zh-state--empty';
        stateEl.replaceChildren(
          el('span', { class: 'zh-state__title', text: 'Keine Treffer für diese Filter' }),
          el('span', { text: 'Zeitraum erweitern, Sammlung abwählen oder das Stichwort löschen – alle Schaltflächen haben Tastaturfokus.' }),
        );
      }
    } else {
      if (stateEl) stateEl.hidden = true;
      listEl.replaceChildren(...filtered.map((record, index) => renderItem(record, index)));
    }
    updateCount(filtered);
  }, 40);

  function updateCount(filtered) {
    const state = ctx.store.getState();
    const parts = [`${filtered.length} von ${records.length} Datensätzen`, `${state.from}–${state.to}`];
    if (state.provider) parts.push(state.provider);
    if (state.type) parts.push(TYPE_LABELS[state.type] ?? state.type);
    if (state.q) parts.push(`„${state.q}“`);
    countEl.textContent = parts.join(' · ');
    if (liveEl) liveEl.textContent = `${filtered.length} Treffer. ${filtered[0] ? `Erster Treffer: ${filtered[0].title}.` : ''}`;
  }

  function apply() {
    const state = ctx.store.getState();
    const filtered = sortRecords(filterRecords(state, records), state.sort);
    if (textEl && textEl.value !== state.q) textEl.value = state.q;
    if (sortEl && sortEl.value !== state.sort) sortEl.value = state.sort;
    if (yearFrom && document.activeElement !== yearFrom) yearFrom.value = String(state.from);
    if (yearTo && document.activeElement !== yearTo) yearTo.value = String(state.to);
    if (yearFill) {
      const span = Math.max(1, years.max - years.min);
      const left = ((state.from - years.min) / span) * 100;
      const right = 100 - ((state.to - years.min) / span) * 100;
      yearFill.style.left = `${Math.max(0, Math.min(100, left))}%`;
      yearFill.style.right = `${Math.max(0, Math.min(100, right))}%`;
    }
    if (overlayEl && overlayEl.value !== state.overlay) {
      overlayEl.value = state.overlay;
      const layer = layers.find((l) => l.id === state.overlay) ?? null;
      applyOverlay(layer, state.otime || layer?.timeValues?.[0]);
    }
    for (const input of document.querySelectorAll('#provider-filters input')) input.checked = input.value === state.provider;
    for (const input of document.querySelectorAll('#type-filters input')) input.checked = input.value === state.type;
    for (const item of listEl.children) {
      const button = item.querySelector('button');
      button?.setAttribute('aria-current', button?.id === `result-${state.selected.replace(/[^\w-]/g, '_')}` ? 'true' : 'false');
    }
    ctx.bus.emit('records:filtered', { records: filtered, state });
    render(filtered);
  }

  // Keyboard navigation inside the list (the map is optional; the list is not).
  listEl.addEventListener('keydown', (event) => {
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
    const buttons = [...listEl.querySelectorAll('button.zh-result')];
    const current = buttons.indexOf(document.activeElement);
    if (current === -1 && event.key !== 'Home' && event.key !== 'End') return;
    event.preventDefault();
    const next =
      event.key === 'ArrowDown' ? Math.min(buttons.length - 1, current + 1)
      : event.key === 'ArrowUp' ? Math.max(0, current - 1)
      : event.key === 'Home' ? 0
      : buttons.length - 1;
    buttons[next]?.focus();
    buttons[next]?.scrollIntoView({ block: 'nearest' });
  });

  ctx.bus.on('records:loaded', () => apply());
  ctx.store.subscribe((_, changed) => {
    if (changed.some((key) => ['from', 'to', 'provider', 'type', 'q', 'sort', 'overlay', 'otime'].includes(key))) apply();
    else if (changed.includes('selected')) {
      for (const item of listEl.children) {
        const button = item.querySelector('button');
        button?.setAttribute('aria-current', button?.id === `result-${ctx.store.getState().selected.replace(/[^\w-]/g, '_')}` ? 'true' : 'false');
      }
    }
  });

  setYearBounds();
  apply();

  return { apply, get filtered() { return lastFiltered; } };
}

function clampYear(value, years) {
  const number = Number(value);
  if (!Number.isFinite(number)) return years.min;
  return Math.max(years.min, Math.min(years.max, Math.round(number)));
}

